"""Reassemble the original PDF bytes for the Coral Anh demo only."""
from pathlib import Path
import hashlib
import base64
import zlib
root = Path(__file__).resolve().parent.parent
parts = root / "site_assets/demo/coral-anh-pdf-parts"
data = b"".join((parts / f"{i:02d}.part").read_bytes() for i in range(8))
assert len(data) == 8367268
assert hashlib.sha256(data).hexdigest() == "f9444b9b030b736b6d3505cb70e84f46a2a95344c04f26029b1f0fb7cd457b0b"
target = root / "public/demo/coral-anh/coral-anh-menu.pdf"
target.parent.mkdir(parents=True, exist_ok=True)
# Preserve the original three menu pages byte-for-byte. The former signed
# attachment is superseded by the revised PDF; no stale signature is retained.
base = data[:8342316]
assert hashlib.sha256(base).hexdigest() == "72e28877a9e0f86edcd59fe5f8430a6aa524024120df7668e057f80a3cdc7e9f"
# Validated incremental PDF revision: vector contact page and six live links.
contact_revision = zlib.decompress(base64.b64decode(""))
result = base + contact_revision
assert hashlib.sha256(result).hexdigest() == "f25f0c36749f625bdc5401b544f88196d2d442cf90112800bf4b22e7f5b4c25d"
target.write_bytes(result)
